if (empty($_SESSION['unit_admin'])) { ?>
<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Login Admin Unit</title><style>body{margin:0;min-height:100vh;display:grid;place-items:center;background:#f5f6f3;font-family:Inter,Segoe UI,sans-serif;color:#173d2a}.login{width:min(420px,calc(100% - 32px));background:#fff;padding:34px;border:1px solid #dfe6df;border-radius:10px;box-shadow:0 18px 45px #18352217}h1{font-size:1.6rem;margin:0 0 8px}p{color:#637067}label{display:grid;gap:6px;font-size:.85rem;font-weight:700;margin:16px 0}input{padding:12px;border:1px solid #dfe6df;border-radius:6px;font:inherit}button{width:100%;padding:13px;border:0;border-radius:6px;background:#145c39;color:#fff;font-weight:800;cursor:pointer}.error{padding:10px;background:#fff2f2;color:#a12121;border-radius:6px;font-size:.86rem}</style><link rel="stylesheet" href="../assets/css/admin.css"><link rel="stylesheet" href="../assets/css/admin-foundation-refresh.css"></head><body><form class="login" method="post"><img class="login-logo" src="<?php echo unit_asset('assets/images/logo.png'); ?>" alt="Logo unit"><p>PORTAL UNIT</p><h1>Masuk ke Admin</h1><p>Kelola publikasi dan administrasi <?php echo unit_e($unit_config['short_name']); ?>.</p><?php if($error): ?><div class="error"><?php echo unit_e($error); ?></div><?php endif; ?><input type="hidden" name="action" value="login"><label>Username<input name="username" required autofocus></label><label>Password<input type="password" name="password" required></label><button>Masuk</button></form></body></html><?php exit; }
$admin=$_SESSION['unit_admin']; $isSuper=$admin['role']==='superadmin'; $scope=$isSuper && isset($allUnits[$_GET['unit']??'']) ? $_GET['unit'] : ($isSuper ? UNIT_SLUG : $admin['unit_slug']);
function admin_upload(string $field, string $unitSlug): ?string { if(empty($_FILES[$field])||($_FILES[$field]['error']??UPLOAD_ERR_NO_FILE)===UPLOAD_ERR_NO_FILE)return null; $file=$_FILES[$field];if($file['error']!==UPLOAD_ERR_OK||$file['size']>6*1024*1024)throw new RuntimeException('Upload gambar gagal atau ukurannya melebihi 6 MB.');$mime=(new finfo(FILEINFO_MIME_TYPE))->file($file['tmp_name']);$ext=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];if(!isset($ext[$mime]))throw new RuntimeException('Gambar harus JPG, PNG, atau WEBP.');$name='media-'.date('Ymd-His').'-'.bin2hex(random_bytes(4)).'.'.$ext[$mime];$dir=dirname(__DIR__,2).'/'.$unitSlug.'/assets/uploads';if(!is_dir($dir))mkdir($dir,0775,true);if(!move_uploaded_file($file['tmp_name'],$dir.'/'.$name))throw new RuntimeException('File tidak bisa disimpan.');return 'assets/uploads/'.$name; }
function admin_allowed_content(string $type): bool{return in_array($type,['program','activity','news','achievement','brochure'],true);}
function admin_media(string $path, string $unitSlug): string {$path=ltrim($path,'/');if($path==='')return ''; $root=preg_replace('~/'.preg_quote(UNIT_SLUG,'~').'$~','',UNIT_BASE_URL);return rtrim($root,'/').'/'.$unitSlug.'/'.$path;}
if ($_SERVER['REQUEST_METHOD']==='POST' && ($_POST['action']??'')!=='login') {
    try { if(!hash_equals($csrf,$_POST['csrf']??'')) throw new RuntimeException('Sesi admin tidak valid.'); $action=$_POST['action']??'';
        if($action==='save_content') { $id=(int)($_POST['id']??0);$type=$_POST['content_type']??'';if(!admin_allowed_content($type))throw new RuntimeException('Jenis konten tidak valid.');$image=admin_upload('image',$scope)??trim($_POST['existing_image']??'');$values=[trim($_POST['title']??''),trim($_POST['summary']??''),trim($_POST['body']??''),$image,trim($_POST['meta']??''),trim($_POST['published_at']??'')?:null,(int)($_POST['sort_order']??0)];if($values[0]==='')throw new RuntimeException('Judul wajib diisi.');if($id){$sql='UPDATE unit_content SET title=?,summary=?,body=?,image=?,meta=?,published_at=?,sort_order=? WHERE id=? AND unit_slug=?';$pdo->prepare($sql)->execute([...$values,$id,$scope]);}else{$pdo->prepare('INSERT INTO unit_content (unit_slug,content_type,title,summary,body,image,meta,published_at,sort_order) VALUES (?,?,?,?,?,?,?,?,?)')->execute([$scope,$type,...$values]);} $notice='Konten disimpan.';
        } elseif($action==='delete_content') {$pdo->prepare('DELETE FROM unit_content WHERE id=? AND unit_slug=?')->execute([(int)$_POST['id'],$scope]);$notice='Konten dihapus.';
        } elseif($action==='save_album') {$id=(int)($_POST['id']??0);$cover=admin_upload('cover_image',$scope)??trim($_POST['existing_image']??'');$values=[trim($_POST['title']??''),trim($_POST['description']??''),$cover,(int)($_POST['sort_order']??0),$scope];if($values[0]==='')throw new RuntimeException('Nama album wajib diisi.');if($id){$pdo->prepare('UPDATE unit_gallery_albums SET title=?,description=?,cover_image=?,sort_order=? WHERE id=? AND unit_slug=?')->execute([...array_slice($values,0,4),$id,$scope]);}else{$pdo->prepare('INSERT INTO unit_gallery_albums (unit_slug,title,description,cover_image,sort_order) VALUES (?,?,?,?,?)')->execute([$scope,...array_slice($values,0,4)]);} $notice='Album disimpan.';
        } elseif($action==='delete_album') {$pdo->prepare('DELETE FROM unit_gallery_albums WHERE id=? AND unit_slug=?')->execute([(int)$_POST['id'],$scope]);$notice='Album dihapus.';
        } elseif($action==='save_photo') {$image=admin_upload('image',$scope);if(!$image)throw new RuntimeException('Pilih foto terlebih dahulu.');$album=(int)$_POST['album_id'];$check=$pdo->prepare('SELECT id FROM unit_gallery_albums WHERE id=? AND unit_slug=?');$check->execute([$album,$scope]);if(!$check->fetch())throw new RuntimeException('Album tidak ditemukan.');$pdo->prepare('INSERT INTO unit_gallery_photos (album_id,title,description,image,sort_order) VALUES (?,?,?,?,?)')->execute([$album,trim($_POST['title']??''),trim($_POST['description']??''),$image,(int)($_POST['sort_order']??0)]);$notice='Foto ditambahkan.';
        } elseif($action==='delete_photo') {$pdo->prepare('DELETE p FROM unit_gallery_photos p JOIN unit_gallery_albums a ON a.id=p.album_id WHERE p.id=? AND a.unit_slug=?')->execute([(int)$_POST['id'],$scope]);$notice='Foto dihapus.';
        } elseif($action==='save_settings') {foreach(['name','tagline','description','phone','whatsapp','email','address','maps','instagram','youtube'] as $key){$pdo->prepare('INSERT INTO unit_settings (unit_slug,setting_key,setting_value) VALUES (?,?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)')->execute([$scope,$key,trim($_POST[$key]??'')]);}$notice='Kontak dan identitas diperbarui.';
        } elseif($action==='save_user' && $isSuper) {$id=(int)($_POST['id']??0);$username=trim($_POST['username']??'');$role=$_POST['role']==='superadmin'?'superadmin':'unit_admin';$userUnit=$role==='superadmin'?null:($_POST['user_unit']??'');if($username==='')throw new RuntimeException('Username wajib diisi.');if($id){$pdo->prepare('UPDATE unit_users SET username=?,role=?,unit_slug=?,is_active=? WHERE id=?')->execute([$username,$role,$userUnit,(int)!empty($_POST['is_active']),$id]);if(trim($_POST['password']??'')!=='')$pdo->prepare('UPDATE unit_users SET password_hash=? WHERE id=?')->execute([password_hash($_POST['password'],PASSWORD_DEFAULT),$id]);}else{if(trim($_POST['password']??'')==='')throw new RuntimeException('Password wajib untuk akun baru.');$pdo->prepare('INSERT INTO unit_users (username,password_hash,role,unit_slug,is_active) VALUES (?,?,?,?,1)')->execute([$username,password_hash($_POST['password'],PASSWORD_DEFAULT),$role,$userUnit]);}$notice='Akun disimpan.';}
    } catch(Throwable $exception){$error=$exception->getMessage();}
