$editContent=null;if(isset($_GET['edit_content'])){$q=$pdo->prepare('SELECT * FROM unit_content WHERE id=? AND unit_slug=?');$q->execute([(int)$_GET['edit_content'],$scope]);$editContent=$q->fetch()?:null;}
$editAlbum=null;if(isset($_GET['edit_album'])){$q=$pdo->prepare('SELECT * FROM unit_gallery_albums WHERE id=? AND unit_slug=?');$q->execute([(int)$_GET['edit_album'],$scope]);$editAlbum=$q->fetch()?:null;}
