columns:1fr}.full{grid-column:auto}.wrap{width:min(100% - 20px,1200px)}.panel{padding:15px}table{font-size:.78rem}.top{padding:12px}.hide-mobile{display:none}}</style><link rel="stylesheet" href="../assets/css/admin.css"><link rel="stylesheet" href="../assets/css/admin-foundation-refresh.css"></head><body><header class="top"><div><img class="portal-logo" src="<?php echo unit_asset('assets/images/logo.png'); ?>" alt="Logo unit"><strong>Portal Unit SIT Permata Hati</strong><br><small><?php echo unit_e($admin['username']); ?> · <?php echo unit_e($isSuper?'Superadmin':strtoupper($admin['unit_slug'])); ?></small></div><a href="?logout=1">Keluar</a></header><main class="wrap"><?php if($isSuper): ?><form class="panel" method="get"><input type="hidden" name="tab" value="<?php echo unit_e($tab); ?>"><label>Pilih unit yang dikelola<select name="unit" onchange="this.form.submit()"><?php foreach($allUnits as $key=>$label): ?><option value="<?php echo $key; ?>" <?php echo $scope===$key?'selected':''; ?>><?php echo $label; ?></option><?php endforeach; ?></select></label></form><?php endif; ?><nav class="tabs"><?php foreach(['dashboard'=>'Dashboard','content'=>'Konten','gallery'=>'Galeri','enrollments'=>'Pendaftar','settings'=>'Kontak','users'=>'Akun'] as $key=>$label):if($key==='users'&&!$isSuper)continue;?><a class="<?php echo $tab===$key?'active':''; ?>" href="?tab=<?php echo $key; ?>&unit=<?php echo unit_e($scope); ?>"><?php echo $label; ?></a><?php endforeach; ?><a href="../index.php" target="_blank">Buka Website</a></nav><?php if($notice): ?><div class="notice"><?php echo unit_e($notice); ?></div><?php endif;if($error): ?><div class="error"><?php echo unit_e($error); ?></div><?php endif; ?>
<?php if($tab==='dashboard'):$counts=[];foreach(['program','activity','news','achievement','brochure'] as $type){$q=$pdo->prepare('SELECT COUNT(*) FROM unit_content WHERE unit_slug=? AND content_type=?');$q->execute([$scope,$type]);$counts[$type]=$q->fetchColumn();}$q=$pdo->prepare('SELECT COUNT(*) FROM unit_enrollments WHERE unit_slug=?');$q->execute([$scope]);?><section class="grid"><?php foreach(['program'=>'Program','activity'=>'Kegiatan','news'=>'Berita','achievement'=>'Prestasi','brochure'=>'Brosur'] as $type=>$label): ?><article class="stat"><span><?php echo $label; ?></span><b><?php echo (int)$counts[$type]; ?></b></article><?php endforeach; ?><article class="stat"><span>Pendaftar Baru</span><b><?php echo (int)$q->fetchColumn(); ?></b></article></section>
