th></tr><?php foreach($rows as $row): ?><tr><td><?php echo unit_e($row['content_type']); ?></td><td><strong><?php echo unit_e($row['title']); ?></strong><br><span class="muted"><?php echo unit_e($row['summary']); ?></span></td><td class="hide-mobile"><?php if($row['image']): ?><img src="<?php echo unit_e(admin_media($row['image'], $scope)); ?>" alt=""><?php endif; ?></td><td><div class="actions"><a href="?tab=content&unit=<?php echo unit_e($scope); ?>&edit_content=<?php echo (int)$row['id']; ?>">Ubah</a><form method="post"><input type="hidden" name="csrf" value="<?php echo $csrf; ?>"><input type="hidden" name="action" value="delete_content"><input type="hidden" name="id" value="<?php echo (int)$row['id']; ?>"><button class="danger">Hapus</button></form></div></td></tr><?php endforeach; ?></table></section>
