></label><label>Urutan<input type="number" name="sort_order" value="0"></label><label>Foto<input required type="file" name="image" accept="image/jpeg,image/png,image/webp"></label><div><button>Tambah Foto</button></div></form></section><section class="panel"><h2>Album dan Foto</h2><table><tr><th>Album / Foto</th><th class="hide-mobile">Preview</th><th>Aksi</th></tr><?php foreach($albums as $album): ?><tr><td><strong>Album: <?php echo unit_e($album['title']); ?></strong><br><span class="muted"><?php echo unit_e($album['description']); ?></span></td><td class="hide-mobile"><?php if($album['cover_image']): ?><img src="<?php echo unit_e(admin_media($album['cover_image'], $scope)); ?>" alt=""><?php endif; ?></td><td><div class="actions"><a href="?tab=gallery&unit=<?php echo unit_e($scope); ?>&edit_album=<?php echo (int)$album['id']; ?>">Ubah</a><form method="post"><input type="hidden" name="csrf" value="<?php echo $csrf; ?>"><input type="hidden" name="action" value="delete_album"><input type="hidden" name="id" value="<?php echo (int)$album['id']; ?>"><button class="danger">Hapus</button></form></div></td></tr><?php endforeach; ?><?php foreach($photosStmt as $photo): ?><tr><td><strong><?php echo unit_e($photo['title']?:'Foto galeri'); ?></strong><br><span class="muted"><?php echo unit_e($photo['album_title']); ?></span></td><td class="hide-mobile"><img src="<?php echo unit_e(admin_media($photo['image'], $scope)); ?>" alt=""></td><td><form method="post"><input type="hidden" name="csrf" value="<?php echo $csrf; ?>"><input type="hidden" name="action" value="delete_photo"><input type="hidden" name="id" value="<?php echo (int)$photo['id']; ?>"><button class="danger">Hapus Foto</button></form></td></tr><?php endforeach; ?></table></section>
